/**
 * Domain Entity: CreateProductGroup
 *
 * Validates payload for creating a product group. The `code` is generated by
 * the use case (PG-### scoped per company), not supplied by the client.
 */
export class CreateProductGroup {
  public readonly name: string;
  public readonly description: string | null;

  constructor(payload: unknown) {
    this._verifyPayload(payload);

    const { name, description } = payload as Record<string, unknown>;

    this.name = (name as string).trim();
    this.description = description ? (description as string).trim() : null;
  }

  private _verifyPayload(payload: unknown): void {
    if (!payload || typeof payload !== 'object') {
      throw new Error('CREATE_PRODUCT_GROUP.NOT_CONTAIN_NEEDED_PROPERTY');
    }

    const { name, description } = payload as Record<string, unknown>;

    if (!name) {
      throw new Error('CREATE_PRODUCT_GROUP.NOT_CONTAIN_NEEDED_PROPERTY');
    }

    if (typeof name !== 'string') {
      throw new Error('CREATE_PRODUCT_GROUP.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }

    if (description !== undefined && description !== null && typeof description !== 'string') {
      throw new Error('CREATE_PRODUCT_GROUP.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }

    if (name.trim().length === 0 || name.trim().length > 100) {
      throw new Error('CREATE_PRODUCT_GROUP.NAME_LIMIT_CHAR');
    }

    if (description && (description as string).trim().length > 500) {
      throw new Error('CREATE_PRODUCT_GROUP.DESCRIPTION_LIMIT_CHAR');
    }
  }
}
